int hits = 0;

for (int i = 0; i < n_points; ++i) {
    double x = rng.uniform(a, b);
    double y = rng.uniform(0.0, fmax);
    if (y <= f->eval(x)) {
        ++hits;
    }
}

double area = (b - a) * fmax;
return (static_cast<double>(hits) / n_points) * area;

